import {GATEWAY_PROVIDERS} from './gateway-catalog.js';
import {CHECKED,SOURCES,MODELS,MODEL,PLANS,PLAN,ROUTES,OFFERS} from './catalog.js';
import {AUTOMATION_SOURCES,automationAssessment} from './automation.js';
import {teamStandardPreset,teamAlternative,scenarioSettings,hybridPreset,technicalTotals,lineSettings,uid,clone,initialState,newLine,newRow,forecast,calculateScenario,costRow,timeProfile,parseImport,validateState,PROFILE_GROUPS,profileTotals,profileLinked,effectiveLine,setAudience,settingsErrors} from './engine.js';
const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let USD=new Intl.NumberFormat(uiLocale(),{style:'currency',currency:'USD',maximumFractionDigits:2});
const RUB=new Intl.NumberFormat('ru-RU',{style:'currency',currency:'RUB',maximumFractionDigits:0});
let nf=new Intl.NumberFormat(uiLocale(),{maximumFractionDigits:2});
const storage='ai-coding-budget-v1';let state=freshState(),openDetails=new Set(),pendingUndo=null,toastTimer;
let storageWarning='';try{const embedded=$('#saved-scenario')?.textContent;if(embedded&&embedded.trim()!=='null')state=parseImport(embedded);else if(localStorage.getItem(storage))state=parseImport(localStorage.getItem(storage));}catch(e){storageWarning='Saved scenario could not be loaded: '+e.message;}
function save(){try{localStorage.setItem(storage,JSON.stringify(state));}catch(e){storageWarning='Local saving is unavailable. Export a JSON backup.';}}
function toast(msg){clearTimeout(toastTimer);$('#toast').textContent=tr(msg);$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,5000);}
function active(){return state.scenarios.find(s=>s.id===state.active)||state.scenarios[0];}
function settings(sc=active()){return scenarioSettings(sc,state.settings);}
function label(l){return l.name||(l.kind==='subscription'?PLAN[l.plan]?.name:l.kind==='openrouter'?'OpenRouter '+({standard:'Standard',business:'Business',byok:'BYOK'}[l.routerPlan]):(GATEWAY_PROVIDERS[l.apiProvider]?.name||'Direct API'));}
function priceRange(lo,hi,cur='usd',fx=settings().fx){const f=cur==='rub'?v=>RUB.format(v*fx):v=>USD.format(v);return Math.abs(hi-lo)<.005?f(lo):f(lo)+' – '+f(hi);}
const input=(bind,title,value,opts={})=>`<label class="field ${opts.wide?'wide':''}"><span>${title}</span><input data-bind="${bind}" type="${opts.type||'number'}" value="${esc(value)}" ${opts.type==='text'||opts.type==='date'?'':`min="${opts.min??0}" max="${opts.max??1000000000}" step="${opts.step??'any'}"`} ${opts.readonly?'readonly aria-readonly="true"':''} ${opts.placeholder?`placeholder="${esc(opts.placeholder)}"`:''}></label>`;
const select=(bind,title,value,options,wide=false)=>`<label class="field ${wide?'wide':''}"><span>${title}</span><select data-bind="${bind}">${options.map(o=>`<option ${bind.endsWith(".bonusSource")&&o[0]?"data-user-content":""} value="${esc(o[0])}" ${String(value)===String(o[0])?'selected':''} ${o[2]?'disabled':''}>${esc(o[1])}</option>`).join('')}</select></label>`;
const check=(bind,title,value)=>`<label class="check-row"><input data-bind="${bind}" type="checkbox" ${value?'checked':''}><span>${title}</span></label>`;
const detail=(id,title,body)=>`<details class="details" data-detail="${id}" ${openDetails.has(id)?'open':''}><summary>${title}</summary>${body}</details>`;
const sourceLink=id=>{const s=SOURCES.find(s=>s.id===id);return s?`<a href="${s.url}" target="_blank" rel="noopener noreferrer">${esc(s.name)}</a>`:'';};
function automationCallout(l){const a=automationAssessment(l,settings());if(!a)return '';return `<div class="callout ${a.level==='ok'?'':a.level}"><strong>${a.level==='bad'?'This route is not established for a shared team bot.':a.level==='warn'?'Check the account and billing conditions.':l.kind==='subscription'?'Check subscription automation eligibility.':'Separate API billing for automation.'}</strong>${detail('automation-'+l.id,'Provider account rules & sources',`<p data-localized-content lang="${uiLanguage}">${esc(a.text)}</p><div class="actions">${a.sources.map(k=>`<a href="${AUTOMATION_SOURCES[k]}" target="_blank" rel="noopener noreferrer">${esc(k)}</a>`).join('')}</div>`)}<button class="btn quiet" data-tab="automation">Account guide</button></div>`;}

function automationGuideHTML(){return `<div class="context"><div><span class="eyebrow">Проверено 17 октября 2026</span><h2 class="profile-title">Как подключить серверных агентов</h2><p class="muted profile-intro">Режим запуска, identity и способ оплаты — три разных решения. Headless не означает API-billing, а API-совместимый URL не означает, что подписка разрешает любой бот.</p></div><button class="btn" data-tab="team">К профилю</button></div><div class="callout"><strong>Практический вариант для команды из 10 разработчиков</strong><p>Именные подписки — для людей. Общие CI, ночные проверки и боты — отдельные API service accounts / system keys с бюджетами и очередью. Личный headless можно оставить на подписке владельца, если это допускают правила продукта; расход объединяется с его интерактивной работой.</p></div><div class="architecture-options">
<section class="architecture-option"><span class="eyebrow">01 · универсальный</span><h3>Общий агент через API</h3><p>Свой worker, Agent SDK или CLI с API-авторизацией. OpenAI и Anthropic документируют service accounts; OpenRouter — workspace system keys. Для Z.ai и DeepSeek используйте стандартный API key на сервере; формальная service identity в изученных международных документах не установлена.</p><p><b>Плюсы:</b> отдельный владелец нагрузки, токенный учёт, разделение dev/prod и бюджетов. <b>Цена:</b> переменный счёт, rate limits и стоимость раннера.</p><p><a href="https://developers.openai.com/api/docs/guides/terraform/service-accounts" target="_blank" rel="noopener">OpenAI</a> · <a href="https://platform.claude.com/docs/en/manage-claude/authentication" target="_blank" rel="noopener">Anthropic</a> · <a href="https://openrouter.ai/docs/guides/best-practices/capping-shared-agent-keys" target="_blank" rel="noopener">OpenRouter system keys</a></p></section>
<section class="architecture-option"><span class="eyebrow">02 · личная автоматизация</span><h3>Headless под учёткой сотрудника</h3><p><code>codex exec</code> с ChatGPT login или <code>claude -p</code> с subscription OAuth используют доступ владельца. Claude также документирует личный Agent SDK и <code>claude setup-token</code>; <code>--bare</code> требует API credentials.</p><p><b>Плюсы:</b> можно использовать уже оплаченную подписку. <b>Цена:</b> общие лимиты с человеком, зависимость от его доступа и ротации credentials, отсутствие гарантированного числа workers. Этот режим не превращает личную квоту в пул для всех коллег.</p><p><a href="${AUTOMATION_SOURCES.codex}" target="_blank" rel="noopener">Codex exec</a> · <a href="${AUTOMATION_SOURCES.claude}" target="_blank" rel="noopener">Claude auth</a> · <a href="${AUTOMATION_SOURCES.claudelegal}" target="_blank" rel="noopener">Границы использования Claude</a></p></section>
<section class="architecture-option"><span class="eyebrow">03 · Codex workspace</span><h3>Access token или native service account</h3><p>Business/Enterprise personal access token запускает Codex от имени пользователя. Native service account — отдельная нечеловеческая identity; доступна <b>только на PAYG-планах</b>, CLI ≥ 0.142.0. Это разные механизмы.</p><p><b>Плюсы:</b> штатные права, группы и аудит, без «фамильной» учётки для native service account. <b>Цена:</b> workspace metered billing и доступность нужного плана; цену credit проверяют по договору. WIF для Codex — beta по включению workspace, не автоматическая функция любой подписки.</p><p>В калькуляторе: «Codex · service account PAYG», включённая квота 0. Фиксированная плата и курс credit — по вашему договору. Этот расчёт не равен Platform API invoice.</p><p><a href="${AUTOMATION_SOURCES.pat}" target="_blank" rel="noopener">Access tokens</a> · <a href="${AUTOMATION_SOURCES.service}" target="_blank" rel="noopener">Service accounts</a> · <a href="${AUTOMATION_SOURCES.wif}" target="_blank" rel="noopener">WIF beta</a></p></section>
<section class="architecture-option"><span class="eyebrow">04 · GLM Coding Plan</span><h3>Поддерживаемый инструмент с Plan Key</h3><p>Coding Plan Key расходует personal или Team seat. Headless не запрещён сам по себе: Z.ai документирует OpenClaw daemon и bot channels. Однако §4 ограничивает использование поддерживаемыми инструментами и конкретным пользователем.</p><p><b>Плюсы:</b> фиксированная цена и скидки расхода credits вне пика. <b>Цена:</b> отдельные квоты seat, динамический параллелизм, best-effort приоритет general-purpose agents. Свой SDK/backend/бот, proxy и обслуживание других пользователей требуют отдельного письменного соглашения; Team это ограничение не снимает.</p><p><a href="${AUTOMATION_SOURCES.glm}" target="_blank" rel="noopener">Subscription Terms §4</a> · <a href="https://docs.z.ai/devpack/tool/openclaw" target="_blank" rel="noopener">OpenClaw</a> · <a href="${AUTOMATION_SOURCES.glmkey}" target="_blank" rel="noopener">Тип ключа и оплата</a></p></section>
<section class="architecture-option"><span class="eyebrow">05 · несколько моделей</span><h3>OpenRouter system key / BYOK</h3><p>Один endpoint и несколько provider routes, отдельный system key на сервис. BYOK подключает upstream API credentials; перенос подписок ChatGPT, Claude или GLM Coding Plan в такой пул <b>не подтверждён</b>.</p><p><b>Плюсы:</b> маршрутизация, fallback, бюджеты и единый учёт. <b>Цена:</b> комиссии, отличие endpoint-цен и upstream limits. System key не подчиняется member budget: задайте его собственный cap. У части prepaid-аккаунтов запросы резервируют средства и могут получить 402 даже при положительном балансе.</p><p><a href="https://openrouter.ai/docs/guides/overview/auth/byok" target="_blank" rel="noopener">BYOK</a> · <a href="https://openrouter.ai/docs/guides/best-practices/capping-shared-agent-keys" target="_blank" rel="noopener">Agent key budgets</a> · <a href="${AUTOMATION_SOURCES.router}" target="_blank" rel="noopener">Лимиты</a></p></section>
<section class="architecture-option"><span class="eyebrow">06 · гибрид</span><h3>Подписки людям + API автоматизации</h3><p>Сохраните привычный инструмент людям, а сервисам выдайте отдельные identities. Подходящие Max/Team планы Claude могут дать monthly API bonus в связанном Console org. Это отдельный кредит, не общий остаток квот seats.</p><p><b>Плюсы:</b> разделение ответственности и личных лимитов, можно направить бонус на собственный headless/SDK с API key. <b>Цена:</b> два контура оплаты. Бонус не покрывает OAuth-headless, interactive Code и официальный Claude Code GitHub Action — даже если Action использует <code>-p</code>.</p><p><a href="https://support.claude.com/en/articles/17154008-monthly-api-credits-for-max-and-team-plans" target="_blank" rel="noopener">Точные условия API bonus</a> · <a href="https://code.claude.com/docs/en/github-actions" target="_blank" rel="noopener">GitHub Action</a></p></section></div>
<section class="section prose"><h3>Как считать без двойной оплаты и двойной квоты</h3><p>Количество технических учёток задаёт независимые identities, а не процессы. Вход/выход в профиле — совокупный дневной расход всех workers одной identity. Число workers только описывает желаемый параллелизм: оно не увеличивает квоты и не умножает токены повторно.</p><p>Если сервер использует уже оплаченную учётку сотрудника, не добавляйте её ещё раз как новую подписку. Объедините человеческую и серверную нагрузку этой identity в одной ручной позиции, учтите общие окна квот, а из остальных позиций исключите её повторную оплату. Автоматического объединения квот между позициями здесь нет. Для нескольких расписаний или всплесков укажите измеренное покрытие; средняя дневная нагрузка не гарантирует прохождения burst.</p><p>Технический профиль имеет собственные дни и часы; временные скидки DeepSeek и GLM пересчитываются по нему. Human-профиль остаётся отдельно. Ключи не вводятся в калькулятор и запросы провайдерам не отправляются. Раннер, VM и наблюдаемость добавляются в «Другие сервисы, $/месяц».</p><h3>Выдержит ли всю команду?</h3><p>Считать надо одновременно активные вызовы и токены в минуту. Пример инженерной оценки: 10 разработчиков × 3 одновременных вызова + 2 агента × 5 = <b>40 in-flight запросов</b>. Это ниже опубликованных DeepSeek account caps 500 Pro / 2500 Flash, но не обещает нужную задержку. Aliases, keys и user_id не добавляют ёмкость.</p><p>Ориентир для однородных вызовов: допустимые starts/min ≈ min(RPM, ITPM / input, OTPM / output); допустимое среднее число in-flight ≈ starts/min × длительность в минутах, с учётом отдельного concurrency cap. Cache reads считаются по правилам конкретного провайдера. Подписочные квоты и лимит расходов проверяются отдельно.</p><div class="table-wrap"><table class="table"><thead><tr><th>Путь</th><th>Что ограничивает</th><th>Что измерить</th></tr></thead><tbody><tr><td>OpenAI API</td><td>Лимиты организации/проекта и модели, spend tier</td><td>RPM/TPM, текущий tier и 429</td></tr><tr><td>Anthropic API</td><td>Org RPM / ITPM / OTPM, spend cap, acceleration limits; новые org могут быть Evaluation</td><td>Uncached/write input, output, фактический tier</td></tr><tr><td>GLM Coding Plan</td><td>Личные 5h / weekly credits, динамический concurrency</td><td>Пиковые окна и очередь; проекты ≠ HTTP requests</td></tr><tr><td>DeepSeek API</td><td>Account in-flight: Pro 500 / Flash 2500 по текущим docs</td><td>Latency/queue, 429, общий расход всех keys</td></tr><tr><td>OpenRouter</td><td>Upstream limits, balance/guardrails, возможный in-flight spend budget</td><td>402/429, max_tokens, маршрут и доступный fallback</td></tr><tr><td>Codex / Claude с подпиской</td><td>Общая квота identity; гарантированный headless concurrency не установлен</td><td>Фактический остаток, stop/retry, совместный расход человека</td></tr></tbody></table></div><p><a href="https://developers.openai.com/api/docs/guides/rate-limits" target="_blank" rel="noopener">OpenAI limits</a> · <a href="https://platform.claude.com/docs/en/api/rate-limits" target="_blank" rel="noopener">Anthropic limits</a> · <a href="https://docs.z.ai/devpack/usage-policy" target="_blank" rel="noopener">GLM usage policy</a> · <a href="https://api-docs.deepseek.com/quick_start/rate_limit" target="_blank" rel="noopener">DeepSeek limits</a></p><h3>Минимальная архитектура общего агента</h3><p>Очередь задач → ограниченный worker pool → CLI/SDK/API → результат и журнал расходов. На каждый сервис — собственный credential, отдельный бюджет и права репозитория. Ошибки 429 обрабатываются с backoff; 402 сначала классифицируются. Повторы LLM-вызова не должны повторно выполнять уже завершённые внешние действия. Для изменений кода результатом служит patch/PR на проверку.</p><p>WIF снижает зависимость от долгоживущих секретов: OpenAI API и Anthropic API имеют собственные механизмы, OpenRouter — Business/Enterprise; доступность Codex WIF требует отдельного включения beta. Ни WIF, ни новый ключ не создают новую квоту.</p><p>Не установлены: универсальная SLA/concurrency подписок, право использовать Claude Primary Owner service account как общий coding pool и право произвольного CI на GLM Coding Plan. Страна серверов, пользователей и оплаты проверяется отдельно от стоимости и гражданства; создание техучётки не отменяет требования доступности/KYC.</p></section>`;}





function modelOptions(l){const p=PLAN[l.plan];return MODELS.filter(m=>l.kind==='subscription'?!m.gatewayOnly&&(p?.family==='custom'||(p?.family==='glm'?!!m.glm:p?.onlyLuna?m.id==='luna':m.provider===p?.family)):l.kind==='openrouter'?(m.id==='custom'||!!ROUTES[m.id])&&(!m.gatewayOnly||m.provider==='openrouter'):l.apiProvider?m.provider===l.apiProvider&&(!m.allowedKinds||m.allowedKinds.includes('api')):!m.gatewayOnly).sort((a,b)=>l.kind==='openrouter'?Number(!!b.gatewayOnly)-Number(!!a.gatewayOnly):0).map(m=>[m.id,m.name+(l.kind==='openrouter'&&!m.gatewayOnly?' · 17 Oct snapshot':'')]);}

function rowHTML(l,row,i,result){const b='r.'+l.id+'.'+row.id+'.',m=MODEL[row.model],route=(ROUTES[m.id]||[]).find(x=>x.id===row.route),mix=l.volumeMode==='mix',prices=row.customRates||(l.kind==='openrouter'&&route?route.rates:m.rates);const speeds=[['standard','Standard']];if(m.provider==='openai'){speeds.push(['fast','Fast ×2'],['batch','Batch ×0.5'],['flex','Flex ×0.5']);if(m.ultrafast)speeds.push(['ultrafast','Ultrafast ×6']);}if(m.provider==='anthropic'){speeds.push(['batch','Batch ×0.5']);if(m.fast)speeds.push(['fast','Fast ×2']);}const compatible=l.kind==='subscription'?speeds.filter(x=>!['batch','flex'].includes(x[0])):l.kind==='openrouter'?[['standard','Selected route rate']]:speeds;
return `<div class="model-row" data-row="${row.id}"><div class="model-main ${mix?'mix':''}">${select(b+'model','Model',row.model,modelOptions(l))}${mix?input(b+'share','Share, %',row.share,{max:100}):input(b+'input','Input, M tokens',row.input)}${mix?'':input(b+'output','Output, M tokens',row.output)}${input(b+'cache','Cached input, %',row.cache,{max:100})}<div class="row-price" data-row-price="${row.id}">${result?USD.format(result.cost):'—'}<div class="small muted">API equivalent / month</div></div><button class="btn icon quiet danger" data-action="remove-row" data-line="${l.id}" data-id="${row.id}" aria-label="Remove model ${esc(m.name)}">×</button></div>${l.kind==='openrouter'?select(b+'route','Provider route',row.route,(ROUTES[m.id]||[{id:'custom',name:'Custom endpoint — enter rates'}]).map(r=>[r.id,r.name])):''}${detail('row-'+row.id,'Cache, speed & custom rates',`<div class="model-extra">${input(b+'writes','Cache writes, % of misses',row.writes,{max:100})}${select(b+'ttl','Claude cache TTL',row.ttl,[['5m','5 minutes'],['1h','1 hour']])}${select(b+'speed','Processing mode',row.speed,compatible)}${input(b+'long',m.threshold?'Tokens in requests > '+nf.format(m.threshold)+', %':m.longPricingUnknown?'Long context, % (quote required)':'Long context, % (no surcharge)',row.long,{max:100})}${input(b+'geo',m.provider==='anthropic'?'US-only inference surcharge, %':'Regional surcharge, %',row.geo,{max:100})}</div><p class="inline-help">Input includes cache. Output includes billable reasoning. Long-context share applies to tokens in individual requests above the threshold.</p><div class="grid four">${prices.map((v,j)=>input('rate.'+l.id+'.'+row.id+'.'+j,(m.currency==='RUB'?['Input RUB/M','Cache write RUB/M','Cache read RUB/M','Output RUB/M']:['Input $/M','Cache write $/M','Cache read $/M','Output $/M'])[j],v)).join('')}</div><p class="inline-help">${row.customRates?'Custom rates replace catalogue prices; time discounts are not applied again.':'Catalogue snapshot: '+(m.checked||CHECKED)}</p><button class="btn quiet" data-action="reset-rates" data-line="${l.id}" data-id="${row.id}">Reset rates</button> ${sourceLink(m.source)}`)}</div>`;}

function lineExtra(l){const b='l.'+l.id+'.',p=PLAN[l.plan];let html=`<div class="grid">${select(b+'kind','Billing type',l.kind,[['subscription','Subscription / Codex workspace'],['api','API · direct or gateway'],['openrouter','OpenRouter']])}${l.kind==='subscription'&&p?.team?'':input(b+'org','Account / organisation / team',l.org,{type:'text'})}${input(b+'extraUsd','Other services, $/month',l.extraUsd)}${input(b+'monthlyCredit','Confirmed credit, $/month',l.monthlyCredit)}</div>${check(b+'holiday','All direct DeepSeek usage falls on a confirmed Chinese public holiday',l.holiday)}`;
if(l.kind==='subscription'){
html+=`<div class="grid">${p.team?'':input(b+'spareSeats','Additional unused seats',l.spareSeats??Math.max(0,l.seats-l.users),{max:10000,step:1})}${input(b+'unitPrice','Custom seat price, $/month equivalent',l.unitPrice??'',{placeholder:'Catalogue price'})}${input(b+'discount','Additional recurring discount, %',l.discount,{max:100})}${input(b+'intro','First-payment discount, %',l.intro,{max:100})}${input(b+'introUntil','First-payment discount expiry',l.introUntil,{type:'date'})}</div>${check(b+'introConfirmed','First-purchase eligibility and discount stacking confirmed at checkout',l.introConfirmed)}<p class="inline-help">Annual and quarterly discounts are already in the seat price. Custom prices are monthly equivalents; upfront payment is multiplied by the billing period.</p>`;
if(p.metered)html+=`<div class="grid">${input(b+'creditUsd','USD / Codex credit · contract rate',l.creditUsd,{step:.001})}${check(b+'creditConfirmed','Credit rate confirmed for this workspace',l.creditConfirmed)}</div><p class="inline-help">Service-account PAYG has no included allowance. Enter any contractual fixed fee separately.</p>`;
else if(p.family==='glm')html+=`<div class="grid">${select(b+'overflow','When quota is exceeded',l.overflow,[['stop','Stop · no paid fallback'],['payg',p.team?'Team overage enabled':'Separate PAYG fallback']])}${input(b+'extraCredits','Other credits / person / week',l.extraCredits)}</div>${p.team?check(b+'glmOveragePromo','Apply current 10% Team overage offer (no announced end date)',l.glmOveragePromo):''}<p class="inline-help">Coding Plan keys use seat quotas. Standard API keys bill separately. Quota is shared across models within one seat, not between people.</p>`;
else html+=`<div class="grid">${select(b+'coverageMode','Included usage',l.coverageMode,[['unknown','Unknown · show cost range'],['manual','Use measured coverage']])}${input(b+'coverage','Workload covered by subscription, %',l.coverage,{max:100})}${p.family==='openai'?input(b+'creditUsd','USD / Codex credit · assumption',l.creditUsd,{step:.001}):''}</div>${p.family==='openai'?check(b+'creditConfirmed','Codex credit price confirmed for my account',l.creditConfirmed):''}<p class="inline-help">Coverage is your measurement for this workload, not a provider guarantee.</p>`;
if(p.family==='anthropic')html+=detail('bundles-'+l.id,'Claude paid usage bundles',`<div class="grid">${input(b+'bundle50','$50 bundles purchased for $45',l.bundle50,{step:1})}${input(b+'bundle250','$250 bundles purchased for $200',l.bundle250,{step:1})}${input(b+'bundle1000','$1,000 bundles purchased for $700',l.bundle1000,{step:1})}${input(b+'bundleMonths','Balance carryover, months · assumption',l.bundleMonths??1,{min:1,max:36,step:1})}</div>${check(b+'bundleRecurring','Purchase this number of bundles every month',l.bundleRecurring)}<p class="inline-help">Counts are for this whole plan. Personal discounted face-value cap: $2,000/account/month; Team: $3,000/workspace/month. Unused credit is not a cash refund. Default carryover is one month; confirm your account terms.</p>`);
}
if(l.kind==='openrouter')html+=`<div class="grid">${select(b+'routerFeeScope','Funding-fee scope',l.routerFeeScope||'line',[['account','Shared billing account'],['line','Per line · legacy estimate']])}</div><p class="inline-help">Card top-ups are assumed. Use the same account name and funding settings to charge one purchase fee across models.</p><div class="grid">${select(b+'routerPlan','OpenRouter plan',l.routerPlan,[['standard','Standard · 5.5%'],['business','Business · 8%'],['byok','BYOK · own provider keys']])}${input(b+'topups','Top-ups / month',l.topups,{min:1,step:1})}${input(b+'feeMin','Minimum fee / top-up, $',l.feeMin??'',{placeholder:l.routerPlan!=='business'?'0.80':'Unconfirmed'})}${input(b+'providerDiscount','BYOK provider discount, %',l.providerDiscount,{max:100})}${input(b+'byokPrior','Other BYOK list-price usage / month, $',l.byokPrior)}</div><p class="inline-help">BYOK’s $25,000 threshold is shared by lines with the same organisation. Endpoint rates already include published route discounts.</p>${check(b+'startup','Startup programme approved for this account',l.startup)}<div class="grid">${input(b+'startupDate','Startup approval date',l.startupDate,{type:'date'})}${input(b+'startupGrant','Remaining Startup grant, $',l.startupGrant,{max:3000})}</div><p class="inline-help">Grant usually lasts 6 months; fee waiver lasts 12. The grant does not pay an external BYOK provider invoice.</p>`;
if(l.kind==='api'&&GATEWAY_PROVIDERS[l.apiProvider])html+=gatewayPlanControlsHTML(l,false);
if(l.kind==='api'&&!GATEWAY_PROVIDERS[l.apiProvider]){const sources=active().lines.filter(x=>x.kind==='subscription'&&PLAN[x.plan]?.family==='anthropic'&&PLAN[x.plan]?.bonus);html+=`<div class="grid">${select(b+'apiRuntime','Integration · Claude bonus eligibility',l.apiRuntime||'own',[['own','Own API / SDK / headless with API key'],['claude-action','Official Claude Code GitHub Action']])}${select(b+'bonusSource','Claude API bonus source',l.bonusSource,[['','Do not apply'],...sources.map(x=>[x.id,label(x)])])}</div>${check(b+'bonusConfirmed','Claim, 7-day wait and linked Console eligibility confirmed',l.bonusConfirmed)}<p class="inline-help">Bonus excludes OAuth headless, interactive Code, the official Code GitHub Action and subscription overage. Team grants cap at $500/org; personal grants are not automatically multiplied by seats.</p>`;}
return html+`<div class="grid">${input(b+'grantOnce','Confirmed one-time credit, $',l.grantOnce)}${input(b+'grantUntil','One-time credit expiry',l.grantUntil,{type:'date'})}</div><p class="inline-help">Without an expiry, one-time credit is used only in the first month. Unused balances are not cash refunds.</p>`;
}

function lineResultHTML(r,first){if(!r?.valid)return `<div class="callout bad" role="alert"><strong>Check this plan’s inputs.</strong><p data-localized-content lang="${uiLanguage}">${r?.errors.map(x=>esc(tr(x))).join('<br>')||'Unable to calculate'}</p></div>`;if(r.inactive)return '<p class="inline-help">No users in this group. This plan adds no cost.</p>';let q='';if(r.quota?.groups)q=`<div class="table-wrap"><table class="table"><thead><tr><th>Group</th><th>Credits / week</th><th>Peak 5-hour window</th><th>Status</th></tr></thead><tbody>${r.quota.groups.map(g=>`<tr><td>${audienceName(g.id)}</td><td>${nf.format(g.weekly)} / ${nf.format(r.quota.weekLimit)}</td><td>${nf.format(g.five)} / ${nf.format(r.quota.fiveLimit)}</td><td>${g.fraction<1?'Over quota':'Within quota'}</td></tr>`).join('')}</tbody></table></div>`;else if(r.quota)q=`<p class="inline-help">Per person: ${nf.format(r.quota.weekly)} / ${nf.format(r.quota.weekLimit)} credits per week; ${nf.format(r.quota.five)} / ${nf.format(r.quota.fiveLimit)} in the busiest 5-hour window.</p>`;return `${q}<div class="actions"><span class="badge ${!r.covered?'bad':r.high-r.low>.005?'warn':''}">${!r.covered?'Workload not covered':r.high-r.low>.005?'Included quota unknown':'Based on entered assumptions'}</span><span class="small muted"><span>${r.line.kind==='subscription'?'Direct API equivalent:':'Token usage cost:'}</span> ${USD.format(r.api)} <span>/ month</span></span></div>${r.credits?`<p class="inline-help">Fully metered workload: ${nf.format(r.credits)} Codex credits.</p>`:''}${first?.bundleFace?`<p class="inline-help">First-month bundles: ${USD.format(first.bundleFace)} face value purchased for ${USD.format(first.bundleCash)}. Remaining balance: ${priceRange(first.bundleLeftLow,first.bundleLeftHigh)}.</p>`:''}${r.bundleFace?`<p class="inline-help">Recurring bundles: ${USD.format(r.bundleFace)} face value for ${USD.format(r.bundleCash)}. Remaining balance: ${priceRange(r.bundleLeftLow,r.bundleLeftHigh)}.</p>`:''}${detail('notes-'+r.line.id,'Provider calculation notes',`<ul class="notes" data-localized-content lang="${uiLanguage}">${r.notes.map(n=>`<li>${esc(n)}</li>`).join('')}</ul>`)}${detail('breakdown-'+r.line.id,'Token cost breakdown · API equivalent',`<div class="table-wrap"><table class="table"><thead><tr><th>Model</th><th>Input</th><th>Cache write</th><th>Cache read</th><th>Output</th></tr></thead><tbody>${r.rows.map(x=>`<tr><td>${esc(x.model.name)}</td>${x.components.map(v=>`<td>${USD.format(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="inline-help">API equivalent is a comparison. These tokens are not charged again on top of an included subscription allowance.</p>`)}`;}

function audienceOptions(){return [['all','All developers · '+settings().team],['active','Power + regular · '+settings().profile.filter(g=>g.id!=='light').reduce((n,g)=>n+g.count,0)],...settings().profile.map(g=>[g.id,GROUP_COPY[g.id][0]+' · '+g.count]),['technical','Server agents · '+settings().technical.count],['manual','Enter people and usage manually']];}






function catalogHTML(){return `<div class="context"><div><h2>Тарифы и акции</h2><p class="small muted">Срез ${CHECKED}. GLM personal, GLM Team и Business перепроверены 17.10. Ручные изменения делаются внутри модели.</p></div></div><h3>API · USD за миллион токенов</h3><div class="table-wrap"><table class="table"><thead><tr><th>Модель</th><th class="right">Input</th><th class="right">Write</th><th class="right">Read</th><th class="right">Output</th><th>Особенности</th></tr></thead><tbody>${MODELS.filter(m=>m.id!=='custom'&&!m.gatewayOnly).map(m=>`<tr><td class="name">${esc(m.name)}</td>${m.rates.map(v=>`<td class="right">${v}</td>`).join('')}<td class="small">${m.timed?'Peak цена; вне пика ×0.5':m.threshold?'Порог отдельного запроса '+nf.format(m.threshold):'Стандартный режим'}<small>${sourceLink(m.source)}</small></td></tr>`).join('')}</tbody></table></div><section class="section"><h3>Подписки и Codex workspace</h3><p class="inline-help">DeepSeek представлен прямым API; у OpenRouter Standard/Business учитывается комиссия, без опубликованной платы за seat. GLM Team не смешивает уровни; OpenAI и Claude допускают Standard/Premium в одной группе. Не передавайте один личный аккаунт всей команде.</p><div class="table-wrap"><table class="table"><thead><tr><th>План</th><th class="right">Monthly</th><th class="right">Quarterly / месяц</th><th class="right">Annual / месяц</th><th>Места / квоты</th></tr></thead><tbody>${PLANS.filter(p=>p.family!=='custom').map(p=>`<tr><td>${p.name}</td><td class="right">${p.metered?'По расходу':USD.format(p.monthly)}</td><td class="right">${p.quarterly!=null?USD.format(p.quarterly):'—'}</td><td class="right">${p.annual!=null?USD.format(p.annual):'—'}</td><td><small>${p.metered?'Нечеловеческая identity; PAYG':p.team?'От '+p.min+' мест'+(p.max?' · до '+p.max:p.unlimitedSeats?' · без верхнего предела мест':' · верхний предел не подтверждён'):'Личный аккаунт на человека'}</small>${p.metered?'Нет включённой квоты · '+sourceLink(p.source):p.qw?nf.format(p.qw)+' credits / week · '+nf.format(p.q5)+' / 5h':'Фиксированная токенная квота не опубликована'}</td></tr>`).join('')}</tbody></table></div></section><section class="section"><h3>Акции и условия применения</h3><div class="table-wrap"><table class="table"><thead><tr><th>Предложение</th><th>Статус</th><th>Как считается</th></tr></thead><tbody>${OFFERS.map(o=>`<tr><td class="name">${o[0]}</td><td><span class="badge ${o[1].startsWith('Завершено')?'bad':o[1].includes('подтверж')?'warn':''}">${o[1]}</span></td><td>${o[2]}<small>${sourceLink(o[3])}</small></td></tr>`).join('')}<tr><td>Claude usage bundles</td><td>Выбор пользователя</td><td>$50 за $45; $250 за $200; $1,000 за $700. Покупка и остаток считаются отдельно. <a href="https://support.claude.com/en/articles/14246112-buy-usage-bundles" target="_blank" rel="noopener noreferrer">Источник</a></td></tr></tbody></table></div></section><section class="section"><h3>Источники</h3><div class="sources-list">${SOURCES.map(s=>`<div class="source"><a href="${s.url}" target="_blank" rel="noopener noreferrer">${esc(s.name)}</a><small>Проверено: ${s.date}</small></div>`).join('')}</div></section>`;}
function methodHTML(){return `<div class="method"><h2>Как устроен расчёт</h2><p>Калькулятор оценивает стоимость заданного расхода. Он не покупает подписки, не вызывает платные API и не обещает равное качество моделей. Курс 95 ₽/$ — ваша настройка, не текущая биржевая котировка.</p><h3>1. Сценарии, позиции, пользователи</h3><p>Сценарий — альтернатива закупки. Внутри него позиции складываются: например, 7 Standard + 3 Premium + отдельный API. Между сценариями суммы не складываются. Один разработчик может пользоваться несколькими подписками; число seats не равно уникальному числу людей. Доля нагрузки позиции применяется к input/output выбранной группы, но не уменьшает количество оплаченных мест. Для GLM + Codex распределяйте суммарно 100% нагрузки группы; доли моделей внутри каждой позиции тоже должны составлять 100%. Новые сценарии, включая готовый гибрид, сохраняют собственные профиль, курс и расписание. Исходные сценарии без собственного профиля продолжают использовать общий; добавление гибрида их не меняет. В профиле задаются три группы, количество людей и токены на человека в день. Команда — сумма групп. Позиция может получать людей и расход из всей команды или одной группы; в ручном режиме вводится одно количество подписок/мест. Неиспользуемые покупки скрыты в дополнительных настройках.</p><p>Annual и quarterly показываются одновременно как месячный эквивалент и реальная предоплата первого периода. Разовая скидка применяется только к первому invoice; она не превращается в постоянный monthly discount. Годовой прогноз предполагает неизменные базовые тарифы и объём.</p><p>Количество и расход связанных позиций меняются автоматически. Для GLM квота и перерасход считаются отдельно по группам, без усреднения лимитов. Для других подписок ручной процент покрытия относится ко всем выбранным людям; чтобы указать разные проценты, создайте позиции по группам. Подключение нескольких позиций к полной команде учитывает полный профиль в каждой: это несколько отдельных подписок/нагрузок, а не автоматическое деление одного расхода между ними.</p><p>Старые JSON и сохранения преобразуются без изменения расходов: их позиции остаются ручными. Переход к вводу токенов по моделям также включает ручной режим и сохраняет суммарные токены через среднее на человека. Возврат к профилю выбирается явно в поле «Для кого».</p><h3>2. Токены без двойного счёта</h3><p><code>R = I × cache%; W = (I−R) × write%; U = I−R−W</code></p><p><code>API = U×p_input + W×p_write + R×p_read + O×p_output</code></p><p>Все объёмы в миллионах. Выход включает billable reasoning. Cached input не добавляется повторно поверх общего I. Write — отдельная категория, не обычный input плюс ещё полная цена записи. В режиме долей процент применяется к input и output; для разных соотношений используйте явные токены по моделям. Сумма процентов должна равняться 100%.</p><h3>3. Расписание и окна GLM</h3><p>По умолчанию равномерное распределение по рабочим часам понедельник–пятница. Расчёт использует шаг 15 минут, учитывает UTC-сдвиг, переход через полночь и выходные. GLM peak 06–10 UTC (09–13 Москва), DeepSeek 01–04 и06–10 UTC. Ручная доля пика задаёт процент токенов. Для direct DeepSeek есть ручной переключатель китайского праздника; применимость календаря нужно подтвердить отдельно.</p><p>Новые планы GLM: <code>credits = (U×a + R×c + O×b) ×100 × time</code>, когда объёмы в миллионах; GLM-5.3 a/c/b=6.9/1.7/24, Flash=2.3/0.56/8; time=1 в пик,0.5 вне пика. Запись кеша в плане входит в uncached. Модели делят одну квоту seat. Проверяются weekly и максимальные rolling5h при постоянном ежедневном mix. Для ручной доли пика 5h оценка приближённая.</p><p>Превышение оценивается пропорциональной долей постоянного mix. Это не точный invoice: изменение моделей, bursts и момент reset меняют результат. Неиспользованные seats не передают квоту активным. Personal без выбранного fallback показывает необслуженный объём; Team overage должен быть включён. Legacy3× не умножается на квоты новых планов.</p><h3>4. OpenAI и Anthropic</h3><p>Публичные множители подписок не раскрывают фиксированную токенную квоту. Поэтому по умолчанию виден диапазон от цены seats до seats плюс полный платный расход. Это условная оценка при выбранном курсе credits, а не верхняя гарантия счёта. Можно задать измеренное покрытие в процентах — оно явно считается допущением пользователя.</p><p>Codex metered credits не имеют отдельной цены записи кеша. USD/credit подтверждается checkout/контрактом; 0.04 в настройке — редактируемое предположение. Included Fast/Ultra расходуются иначе, чем оплаченные credits. API режима Batch/Flex не следует считать интерактивным сервисом той же скорости.</p><p>Claude API bonus применяется только к отдельной eligible API-позиции после подтверждения claim и Console linkage. Team максимум$500/org, personal не умножается автоматически на число пользователей. Срок остатка bundles задаётся явно, по умолчанию 1 месяц без переноса. Это консервативное допущение, а не подтверждённое правило провайдера. Интерактивные usage bundles — другой механизм: вы платите за номинал; неиспользованный остаток показывается, но не вычитается как возврат. Лимит Team по одной группе, личный лимит на аккаунт; равномерное распределение между личными аккаунтами предполагается пользователем.</p><h3>5. OpenRouter</h3><p>Каждая строка модели использует согласованный endpoint: нельзя комбинировать минимальный input одного хоста и output другого. Ставки альтернативных маршрутов могут уже включать промо. DeepSeek snapshot в выходной может содержать off-peak base: встроенные цены нормализованы к явным peak/off-peak overrides, скидка не применяется дважды.</p><p>Обычный OR счёт = inference + max(процент комиссии, число пополнений × минимум), если действительно нужно пополнение. Это оценка при пополнении ровно под расход, без старого prepaid balance и без округления минимального principal purchase. Business minimum не подтверждён — вводится вручную. Для нескольких бюджетов одного OR аккаунта лучше одна позиция с несколькими моделями.</p><p>BYOK: provider invoice остаётся отдельно; 5% применяется к превышению общего list-price порога$25,000. Позиции одной группы делят порог. Пополнение OR для самой комиссии имеет сбор 5.5% с минимумом $0.80 (можно изменить); по BYOK-группе он считается один раз. Startup grant не оплачивает внешний provider invoice. Fee waiver12месяцев и grantобычно6месяцев различаются.</p><h3>6. Контекст, кеш, география и качество</h3><p>Надбавка long context определяется отдельными запросами. Для OpenAI указанных семейств выше272k: input/read/write×2 иoutput×1.5; Haiku5.5 выше100k — все категории×5. Поле доли длинного контекста предполагает одинаковую долю по категориям. Для другого распределения разделите модель на несколько строк.</p><p>Поля геонаценки вводятся явно. Anthropic first-party +10% относится к US-only inference, не европейскому гражданству. Regional OpenRouter endpoint уже может содержать надбавку; не включайте её дважды. Europe routing включает EU/EEA, UK и Switzerland; юридическую strictEU-only гарантию калькулятор не создаёт.</p><p>Cache hit80% не гарантируется провайдером. Разные tokenizer, reasoning effort, число повторов, инструменты и скорость меняют итоговый расход. KYC, страна нахождения и допустимость оплаты не выводятся из цены или паспорта; см. ${sourceLink('research')}.</p><h3>7. Что сохраняется и чего здесь нет</h3><p>Настройки сохраняются в localStorage этого браузера, не синхронизируются с командой. JSON сохраняет сценарии; скачиваемый HTML сохраняет весь калькулятор, каталог и текущий сценарий и работает офлайн. Здесь нет API-ключей и фоновых запросов к провайдерам. Ссылки на источники открываются только по нажатию.</p><p>Не включены автоматически налоги страны, валютный спред банка, tools/containers/Actions/поиск, SLA и throughput. Их можно добавить как ручной платёж. Калькулятор не превращает годовую предоплату в помесячный договор. Неподтверждённые скидки по умолчанию выключены. Будущие цены и акции требуют перепроверки.</p><h3>Контрольный пример</h3><p>GPT-6.1 Sol,20Minput+1Moutput,80%cache,100%промахов в запись: <code>4×2.5+16×0.1+1×10=$21.60</code>. GLM-5.3 для того же объёма: API$14.16; план7,880credits в пик или5,691.11 при09–18МСК. GLM Pro 60,000 credits/week при пяти таких днях расходует 28,455.56 credits; самое дорогое 5h окно 09–14 —3,940credits.</p></div>`;}
function sidebar(){if($('#scenario-context'))$('#scenario-context').innerHTML=contextHTML();}

function render(){journeyRender();}

function updateResults(){journeyUpdate();}

function bindValue(el,structural=false){const parts=el.dataset.bind.split('.');let value=el.type==='checkbox'?el.checked:el.type==='number'?(el.value===''?null:Number(el.value)):el.value;
 if(parts[0]==='t'){if(value===null)return;settings().technical[parts[1]]=value;}
 else if(parts[0]==='p'){if(value===null)return;const g=settings().profile.find(x=>x.id===parts[1]);if(g)g[parts[2]]=value;settings().team=profileTotals(settings()).count;}
 else if(parts[0]==='g'){if(value===null)return;settings()[parts[1]]=value;}
 else if(parts[0]==='scenario')active().name=String(value).slice(0,120);
 else{
  const l=active().lines.find(x=>x.id===parts[1]);if(!l)return;
  if(parts[0]==='l'){
   if(value===null&&!['unitPrice','feeMin'].includes(parts[2]))return;
   if(parts[2]==='apiProvider'){if(value==='mixed')delete l.apiProvider;else changePlanDraft({line:l,provider:l.apiProvider},'provider',value,settings());}else if(parts[2]==='audience')setAudience(l,value,settings());else if(parts[2]==='quantity'){l.users=value;l.seats=value+(l.kind==='subscription'?(l.spareSeats??0):0);}else{l[parts[2]]=value;}
   if(parts[2]==='spareSeats'&&!profileLinked(l))l.seats=l.users+value;
   if(parts[2]==='plan'){
    l.billing='monthly';l.unitPrice=null;l.coverageMode='unknown';const options=modelOptions(l);const model=options[0]?.[0]||'custom';l.rows=l.rows.filter(r=>options.some(o=>o[0]===r.model));if(!l.rows.length)l.rows=[newRow(model)];if(l.rows.length===1)l.rows[0].share=100;
   }
   if(parts[2]==='kind'&&value==='subscription'){l.plan='glm-pro';l.rows=[newRow('glm')];l.seats=l.users+(l.spareSeats??0);}
   if(parts[2]==='kind'&&value!=='subscription'){l.spareSeats=0;l.seats=l.users;}
   if(parts[2]==='kind'&&value==='openrouter'){changePlanDraft({line:l,provider:'openrouter'},'provider','openrouter',settings());}if(parts[2]==='kind'&&value==='subscription')delete l.apiProvider;
  }else{
   const row=l.rows.find(r=>r.id===parts[2]);if(!row)return;
   if(parts[0]==='rate'){if(value===null)return;if(!row.customRates){const route=l.kind==='openrouter'?(ROUTES[row.model]||[]).find(x=>x.id===row.route):null;row.customRates=[...(route?.rates||MODEL[row.model].rates)];}row.customRates[Number(parts[3])]=value;}
   else{if(value===null)return;row[parts[3]]=value;if(parts[3]==='model'){const fresh=newRow(row.model,row.share);row.customRates=null;row.speed='standard';row.route=fresh.route;row.long=0;row.writes=fresh.writes;if(MODEL[row.model].rates[2]===null)row.cache=0;}if(parts[3]==='route'){row.customRates=null;const route=(ROUTES[row.model]||[]).find(x=>x.id===row.route);if(route?.cacheWriteKnown===false)row.writes=0;}}
  }
 }
 if(structural){render();document.querySelector(`[data-bind="${el.dataset.bind}"]`)?.focus({preventScroll:true});}else updateResults();
}
function download(name,text,type='text/plain'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportHTML(){const doc=document.documentElement.cloneNode(true);const tag=doc.querySelector('#saved-scenario');tag.textContent=JSON.stringify(state).replace(/</g,'\\u003c');doc.querySelector('#toast').hidden=true;doc.querySelector('dialog')?.removeAttribute('open');download('ai-coding-budget.html','<!doctype html>\n'+doc.outerHTML,'text/html');toast('Offline calculator downloaded with your scenarios');}
function exportCSV(){const rows=[['Сценарий','Позиция','Месяц USD минимум','Месяц USD максимум','Месяц RUB минимум','Месяц RUB максимум','Первый платёж USD min','Первый платёж USD max','Вход M','Выход M','Модели','Статус','Применимость автоматизации']];rows[0]=rows[0].map(tr);for(const sc of state.scenarios){const f=forecast(sc,settings(sc));f.regular.lines.forEach((r,i)=>{if(!r.valid)return;const first=f.first.lines[i];rows.push([sc.name,r.line.name||tr(label(r.line)),r.low,r.high,r.low*settings(sc).fx,r.high*settings(sc).fx,first.cashLow,first.cashHigh,r.rows.reduce((a,x)=>a+x.vol.monthly[0],0),r.rows.reduce((a,x)=>a+x.vol.monthly[1],0),r.rows.map(x=>tr(x.model.name)).join(' / '),tr(r.covered?(r.high-r.low>.005?'Квота неизвестна':'По допущениям'):'Не весь объём'),tr(automationAssessment(r.line,settings(sc))?.title||'Люди / ручной сценарий')]);});}const cell=x=>{let s=String(x);if(/^[=+@\-]/.test(s)&&typeof x!=='number')s="'"+s;return '"'+s.replace(/"/g,'""')+'"';};download('ai-budget.csv','\ufeff'+rows.map(r=>r.map(cell).join(';')).join('\r\n'),'text/csv;charset=utf-8');}
function showAdd(){startManualPlan();}

document.addEventListener('input',e=>{if(e.target.matches('[data-budget]')&&e.target.type==='number'){updateBudgetInput(e.target);return;}if(e.target.matches('[data-wizard]')&&['number','text'].includes(e.target.type)){updatePlanDraft(e.target);return;}if(e.target.matches('[data-bind]')&&e.target.tagName!=='SELECT'&&e.target.type!=='checkbox')bindValue(e.target);});
document.addEventListener('change',e=>{if(e.target.matches('[data-budget]')){if(e.target.tagName==='SELECT')updateBudgetInput(e.target);return;}if(e.target.matches('[data-wizard]')){if(e.target.type!=='number')updatePlanDraft(e.target);return;}if(e.target.matches('[data-analytics]')){updateAnalytics(e.target.dataset.analytics,e.target.value);return;}if(e.target.matches('[data-rec]')){updateRecommendationOption(e.target);return;}if(e.target.id==='scenario-picker'){state.active=e.target.value;if(state.tab==='calculator')enterPlans();render();focusPage();return;}if(e.target.matches('[data-bind]')){const key=e.target.dataset.bind.split('.').pop();const structural=e.target.tagName==='SELECT'||e.target.type==='checkbox'||['unitPrice','name'].includes(key);if(structural)bindValue(e.target,true);}if(e.target.id==='import-file'){document.activeElement?.blur();const file=e.target.files[0];if(!file)return;file.text().then(text=>{state=parseImport(text);planJourneys.clear();budgetDrafts.clear();pendingUndo=null;openDetails.clear();render();toast('Scenarios imported');}).catch(e=>toast('Import rejected: '+e.message));e.target.value='';}});
document.addEventListener('toggle',e=>{if(e.target.matches('details[data-detail]')){if(e.target.open)openDetails.add(e.target.dataset.detail);else openDetails.delete(e.target.dataset.detail);}},true);
document.addEventListener('keydown',e=>{if(e.key==='Escape')document.querySelectorAll('.menu[open]').forEach(d=>{d.open=false;d.querySelector('summary').focus();});});
document.addEventListener('click',e=>{document.querySelectorAll('.menu[open]').forEach(d=>{if(!d.contains(e.target)||e.target.closest('[data-action]'))d.open=false;});});
document.addEventListener('click',e=>{
 const lang=e.target.closest('[data-language]');if(lang){changeLanguage(lang.dataset.language);return;}
 const chartMode=e.target.closest('[data-chart-mode]');if(chartMode){updateAnalytics('mode',chartMode.dataset.chartMode);document.querySelector(`[data-chart-mode="${chartMode.dataset.chartMode}"]`)?.focus({preventScroll:true});return;}
 inspectChart(e.target);
 const tab=e.target.closest('[data-tab]');if(tab){if(tab.dataset.tab==='calculator')enterPlans();else state.tab=tab.dataset.tab;render();focusPage();return;}
 const b=e.target.closest('[data-action]');if(!b)return;if(journeyAction(b))return;const act=b.dataset.action,id=b.dataset.id;const sc=active(),l=sc.lines.find(x=>x.id===id);let redraw=true;
 if(act==='select-scenario'){state.active=id;state.tab='calculator';}
 else if(act==='new-scenario'){if(state.scenarios.length>=30){toast('You can save up to 30 scenarios.');return;}const s={id:uid(),name:tr('New team budget'),settings:clone(settings()),lines:[]};state.scenarios.push(s);state.active=s.id;state.tab='team';}
 else if(act==='add-hybrid'){if(state.scenarios.length>=30){toast('Можно сохранить до 30 сценариев');return;}pendingUndo=clone(state);const preset=hybridPreset({...settings(),date:CHECKED});state.scenarios.push(preset);state.active=preset.id;state.tab='calculator';toast('Добавлен гибрид 18 + 1 с отдельным профилем. Другие сценарии сохранены.');}
 else if(act==='add-team-standard'){if(state.scenarios.length>=30){toast('Можно сохранить до 30 сценариев');return;}pendingUndo=clone(state);const preset=teamStandardPreset({...settings(),date:CHECKED});state.scenarios.push(preset);state.active=preset.id;state.tab='calculator';toast('Добавлен GLM Team 18 + Codex 8. Предыдущие расчёты сохранены.');}
 else if(act==='team-alternative'){if(state.scenarios.length>=30){toast('Можно сохранить до 30 сценариев');return;}const copy=teamAlternative(sc,b.dataset.value);state.scenarios.push(copy);state.active=copy.id;state.tab='calculator';}
 else if(act==='hybrid-billing'){for(const line of sc.lines)if(line.kind==='subscription'&&PLAN[line.plan]?.[b.dataset.value]!=null)line.billing=b.dataset.value;}
 else if(act==='clone-scenario'){if(state.scenarios.length>=30){toast('You can save up to 30 scenarios.');return;}const copy=clone(sc);copy.settings=clone(settings());copy.id=uid();copy.name+=' · copy';state.scenarios.push(copy);state.active=copy.id;}
 else if(act==='remove-scenario'){if(state.scenarios.length===1)return;pendingUndo=clone(state);state.scenarios=state.scenarios.filter(x=>x.id!==sc.id);state.active=state.scenarios[0].id;toast('Scenario removed. Restore it with Manage → Undo last removal.');}
 else if(act==='undo'){if(pendingUndo){state=pendingUndo;pendingUndo=null;}}
 else if(act==='add-line'){showAdd();redraw=false;}
 else if(act==='close-dialog'){$('#add-dialog').close();redraw=false;}
 else if(act==='clone-line'){const copy=clone(l);copy.id=uid();copy.name=label(l)+' · copy';copy.rows.forEach(r=>r.id=uid());sc.lines.push(copy);}
 else if(act==='remove-line'){pendingUndo=clone(state);sc.lines=sc.lines.filter(x=>x.id!==id);toast('Plan removed. Restore it with Manage → Undo last removal.');}
 else if(act==='add-row'){const m=modelOptions(l)[0]?.[0]||'custom';const row=newRow(m,l.volumeMode==='mix'?0:100);l.rows.push(row);}
 else if(act==='remove-row'){const line=sc.lines.find(x=>x.id===b.dataset.line);line.rows=line.rows.filter(r=>r.id!==id);}
 else if(act==='reset-rates'){const line=sc.lines.find(x=>x.id===b.dataset.line);line.rows.find(r=>r.id===id).customRates=null;}
 else if(act==='dismiss-migration'){state.migrationNotes=[];}
 else if(act==='add-technical'){startManualPlan('technical');redraw=false;}
 else if(act==='apply-profile'){pendingUndo=clone(state);for(const line of sc.lines)if(!profileLinked(line))setAudience(line,'all',settings());state.tab='calculator';toast('Профиль подключён. Выберите нужную группу у каждой позиции; действие можно отменить.');}
 else if(act==='volume-mode'){const next=b.dataset.value;if(next==='explicit'&&profileLinked(l)){setAudience(l,'manual',settings());toast('Exact tokens use manual workload. To reconnect the profile, choose a team group.');}if(next!==l.volumeMode){if(next==='explicit')l.rows.forEach(r=>{r.input=l.input*r.share/100;r.output=l.output*r.share/100;});else{l.input=l.rows.reduce((a,r)=>a+r.input,0);l.output=l.rows.reduce((a,r)=>a+r.output,0);l.rows.forEach(r=>r.share=l.input>0?r.input/l.input*100:l.output>0?r.output/l.output*100:100/l.rows.length);toast('Shares are based on input tokens. Review the new input/output mix.');}l.volumeMode=next;}}
 else if(act==='export-json'){download('ai-budget-scenarios.json',JSON.stringify({...state,catalogDate:CHECKED},null,2),'application/json');redraw=false;}
 else if(act==='import-json'){$('#import-file').click();redraw=false;}
 else if(act==='export-csv'){exportCSV();redraw=false;}
 else if(act==='export-html'){exportHTML();redraw=false;}
 else if(act==='print'){window.print();redraw=false;}
 if(!redraw)localizeUI();
 if(redraw){render();if(['new-scenario','select-scenario','team-alternative','remove-scenario','clone-scenario'].includes(act))focusPage();}
});
document.addEventListener('mouseover',e=>{if(e.target.closest('[data-chart-month],[data-chart-category]'))inspectChart(e.target);});
document.addEventListener('focusin',e=>{if(e.target.closest('[data-chart-month],[data-chart-category]'))inspectChart(e.target);});
document.addEventListener('keydown',e=>{const mark=e.target.closest('[data-chart-month]');if(!mark)return;if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();let i=Number(mark.dataset.chartMonth);i=e.key==='Home'?0:e.key==='End'?11:Math.max(0,Math.min(11,i+(e.key==='ArrowRight'?1:-1)));document.querySelector(`[data-chart-month="${i}"]`)?.focus();}if(['Enter',' '].includes(e.key)){e.preventDefault();inspectChart(mark);}});
window.aiBudget={getState:()=>clone(state),getForecast:()=>forecast(active(),settings())};
render();
